import{_ as e,o as t,c as a,a2 as i}from"./chunks/framework.CnJ-JtFX.js";const u=JSON.parse('{"title":"EP.10 左右互搏：编辑器和画布是两个独立进程","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.10-tmagic-basics.md","filePath":"comics/EP.10-tmagic-basics.md","lastUpdated":1792683644000}'),n={name:"comics/EP.10-tmagic-basics.md"};function d(s,o,r,c,l,p){return t(),a("div",null,[...o[0]||(o[0]=[i(`<h1 id="ep-10-左右互搏-编辑器和画布是两个独立进程" tabindex="-1">EP.10 左右互搏：编辑器和画布是两个独立进程 <a class="header-anchor" href="#ep-10-左右互搏-编辑器和画布是两个独立进程" aria-label="Permalink to &quot;EP.10 左右互搏：编辑器和画布是两个独立进程&quot;">​</a></h1><blockquote><p>对应章节：<a href="./../guide/10-tmagic-basics">guide/10-tmagic-basics</a></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><ol><li><strong>困境</strong>：标签君把编辑器和画布写成一个 Vue 组件，结果 Monaco 的 chunk 把整个应用塞到 8 MB，画布还被 element-plus 的样式污染；改一个按钮布局，画布上选中框的坐标全乱了。</li><li><strong>揭秘</strong>：码叔指着 index.html 和 runtime.html 两个入口说：<strong>拆成父子进程</strong>。设计器在主窗口、画布在 iframe，中间用 <code>window.magic</code> 传 DSL 和坐标。</li><li><strong>实证</strong>：像素酱跑起 lab，把 DSL 推过去时画布里的 Page 组件立刻渲染出来；拖拽一个 button，iframe 里自动多了一个 DOM 节点。</li><li><strong>结案</strong>：码叔收束到「拆成两个 HTML 不是功能需求，是工程隔离需求」——样式隔离、体积隔离、运行时隔离，一个都不能少。</li></ol><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="第一格-大组件不是解决方案" tabindex="-1">第一格：大组件不是解决方案 <a class="header-anchor" href="#第一格-大组件不是解决方案" aria-label="Permalink to &quot;第一格：大组件不是解决方案&quot;">​</a></h3><p>你可能觉得&quot;Vue 组件能嵌套，把画布写成 <code>&lt;Editor&gt;&lt;Canvas /&gt;&lt;/Editor&gt;</code> 不就行了？&quot;。实际上这会带来三个工程问题：</p><ol><li><strong>样式污染</strong>：编辑器引入 element-plus、Monaco、moveable，这些库的全局样式会影响画布（比如 canvas 里写 <code>.button { color: red }</code>，被 element-plus 的 <code>.el-button</code> 覆盖）；</li><li><strong>体积膨胀</strong>：Monaco-editor 本身就有 2 MB 压缩前，画布根本不需要 Monaco；</li><li><strong>坐标计算</strong>：画布需要 <code>position: absolute</code> 的自由布局，如果和设计器混在同一个 DOM 层级，<code>getBoundingClientRect()</code> 的 offset 会被外层容器稀释，选中框永远对不准。</li></ol><p>iframe 完美解决这三个问题——独立 DOM、独立打包、独立坐标系统。</p><p>对应正文：<a href="./../guide/10-tmagic-basics#从一个真实问题说起">从一个真实问题说起</a>。</p><h3 id="第二格-window-magic-是唯一的桥" tabindex="-1">第二格：window.magic 是唯一的桥 <a class="header-anchor" href="#第二格-window-magic-是唯一的桥" aria-label="Permalink to &quot;第二格：window.magic 是唯一的桥&quot;">​</a></h3><p>两个进程之间唯一&quot;共享&quot;的就是 iframe 里的 <code>window.magic</code> 对象。它由 <code>@tmagic/stage</code> 注入画布进程，包含以下关键方法：</p><table tabindex="0"><thead><tr><th>方法</th><th>调用方</th><th>职责</th></tr></thead><tbody><tr><td><code>onRuntimeReady(callbacks)</code></td><td>画布</td><td>编辑器会推 DSL 过来前先等你把回调挂上</td></tr><tr><td><code>updateRootConfig(dsl)</code></td><td>编辑器</td><td>把完整 MApp DSL 推给画布</td></tr><tr><td><code>updatePageId(id)</code></td><td>编辑器</td><td>切换当前渲染的页面</td></tr><tr><td><code>select(nodeId)</code></td><td>编辑器</td><td>选中某个组件（画布返回元素）</td></tr><tr><td><code>onPageElUpdate(el)</code></td><td>画布</td><td>页面根节点渲染完后回传给编辑器</td></tr></tbody></table><p>画布进程的 <code>useEditorDsl()</code> Hook 内部会自动调用 <code>window.magic?.onRuntimeReady(...)</code>，所以运行时不需要手动写这堆 boilerplate——但你得知道它在干什么。</p><h3 id="第三格-dsl-链路" tabindex="-1">第三格：DSL 链路 <a class="header-anchor" href="#第三格-dsl-链路" aria-label="Permalink to &quot;第三格：DSL 链路&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>编辑器 dsl ref</span></span>
<span class="line"><span>  ↓ updateRootConfig(dsl)</span></span>
<span class="line"><span>window.magic（iframe.contentWindow）</span></span>
<span class="line"><span>  ↓ useEditorDsl 内部处理</span></span>
<span class="line"><span>root.value = reactive(dsl)</span></span>
<span class="line"><span>  ↓ computed pageConfig = root.items[curPageId]</span></span>
<span class="line"><span>Page 组件 :config=&quot;pageConfig&quot;</span></span>
<span class="line"><span>  ↓ Vue 渲染</span></span>
<span class="line"><span>真实 DOM 节点</span></span>
<span class="line"><span>  ↓ onPageElUpdate(el)</span></span>
<span class="line"><span>编辑器画选中框</span></span></code></pre></div><p>整条链路是<strong>响应式的</strong>——中间任何一个节点改了 DSL，画布重新渲染；画布元素位置变了，<code>onPageElUpdate</code> 重新被调。</p><h3 id="第四格-能跑是第一位" tabindex="-1">第四格：能跑是第一位 <a class="header-anchor" href="#第四格-能跑是第一位" aria-label="Permalink to &quot;第四格：能跑是第一位&quot;">​</a></h3><p>不要一开始就想&quot;我要手写一个类似 magic 的通信协议&quot;。tmagic 已经把这件事做死了——<code>window.magic</code> 是 stage 包在 iframe 里注入的，你唯一要做的是：</p><ol><li>runtime/main.ts 创建 <code>TMagicApp({ platform: &#39;editor&#39; })</code>；</li><li>runtime/App.vue 里 <code>const hook = useEditorDsl()</code>；</li><li>编辑器 App.vue 里给 <code>&lt;TMagicEditor :runtime-url=&quot;...&quot;&gt;</code> 传正确地址；</li></ol><p>lab 已经把这三件事都写好了，跑起来以后你再看代码，每一行都有意义。</p><h2 id="逐格解读" tabindex="-1">逐格解读 <a class="header-anchor" href="#逐格解读" aria-label="Permalink to &quot;逐格解读&quot;">​</a></h2><h3 id="第一格-为什么不能把画布写成组件" tabindex="-1">第一格：为什么不能把画布写成组件 <a class="header-anchor" href="#第一格-为什么不能把画布写成组件" aria-label="Permalink to &quot;第一格：为什么不能把画布写成组件&quot;">​</a></h3><p><strong>画面</strong>：标签君在一个 8 MB 的 Vue bundle 前发呆，画布被 element-plus 的按钮样式污染，选中框偏移 30px。码叔从口袋掏出两个独立 HTML 文件。</p><p><strong>台词</strong>：</p><blockquote><p>码叔：「你写的是一个组件，画布是另一个<strong>进程</strong>。进程之间只有 iframe 能隔离样式和体积。」</p></blockquote><h3 id="第二格-window-magic-是桥" tabindex="-1">第二格：window.magic 是桥 <a class="header-anchor" href="#第二格-window-magic-是桥" aria-label="Permalink to &quot;第二格：window.magic 是桥&quot;">​</a></h3><p><strong>画面</strong>：两个浏览器窗口（父窗口 &amp; iframe）之间画一条带 <code>window.magic</code> 标签的线，<code>updateRootConfig</code> 和 <code>onPageElUpdate</code> 箭头双向。</p><p><strong>台词</strong>：</p><blockquote><p>像素酱：「哦…原来它不是 Vue 的 props 透传！」 码叔：「props 是<strong>同一棵树</strong>里的数据流；跨进程只能靠<strong>全局对象 + 函数回调</strong>。」</p></blockquote><h3 id="第三格-推-dsl" tabindex="-1">第三格：推 DSL <a class="header-anchor" href="#第三格-推-dsl" aria-label="Permalink to &quot;第三格：推 DSL&quot;">​</a></h3><p><strong>画面</strong>：编辑器左侧拖了一个 button，DSL 对象变了；iframe 里立刻出现了新的 button DOM 节点；画布下方 Console 里是 <code>[tmagic-runtime] pageConfig updated</code>。</p><p><strong>台词</strong>：</p><blockquote><p>像素酱：「这就是『所见即所得』——编辑器改 DSL，画布自动重渲染。」</p></blockquote><h3 id="第四格-能跑就行" tabindex="-1">第四格：能跑就行 <a class="header-anchor" href="#第四格-能跑就行" aria-label="Permalink to &quot;第四格：能跑就行&quot;">​</a></h3><p><strong>画面</strong>：标签君在看 <code>src/main.ts</code>（Monaco workers + editorPlugin + adapter），画布右下角有一个小小的 debug-bar：<code>pageConfig.id: page_xxx</code>。</p><p><strong>台词</strong>：</p><blockquote><p>码叔：「能跑 &gt; 能读 &gt; 能扩展。先让这页出来，再想为什么。」</p></blockquote><h2 id="坑点清单" tabindex="-1">坑点清单 <a class="header-anchor" href="#坑点清单" aria-label="Permalink to &quot;坑点清单&quot;">​</a></h2><ol><li><strong>Monaco 顺序错了，code editor 永远空白</strong> — MonacoEnvironment 必须在 <code>app.use(editorPlugin, adapter)</code> 之前配。顺序颠倒 Monaco 初始化时找不到 worker 会静默失败，控制台也不报错。</li><li><strong>runtimeUrl 写成了绝对路径 + 端口硬编码</strong> — 用 <code>new URL(&quot;/runtime.html&quot;, location.href).toString()</code> 自动适配当前 host；dev 模式 Vite 同域下直接写相对路径也可以。</li><li><strong>propsConfigs 没配，右侧面板无字段</strong> — 每注册一个新 type 就去 <code>configs/props.ts</code> 加一条 <code>propsConfigs[type] = [...]</code>；否则编辑器不知道该 type 有哪些表单字段可改。</li><li><strong>runtime.html 独立打开时画布空白</strong> — 这是正常的；独立打开没有编辑器推送 DSL，<code>useEditorDsl()</code> 会一直等。加 <code>?localPreview=1</code> 让 runtime 读 localStorage 里的预览 DSL，或让它跑在 iframe 场景。</li><li><strong>updateRootConfig 推了 DSL 但画布没渲染</strong> — 检查 <code>platform</code> 是否是 <code>&quot;editor&quot;</code>（让 core 进入编辑模式），以及 runtime 是否真的挂载了 Vue app。App.vue 里 <code>pageConfig</code> 是 undefined 就说明 DSL 没进来。</li><li><strong>画布渲染完了但选中框对不准</strong> — 画布根节点渲染完必须调 <code>magic.onPageElUpdate(root)</code>，否则 stage 拿不到元素坐标，编辑器画的选中框永远偏。</li></ol><h2 id="自测" tabindex="-1">自测 <a class="header-anchor" href="#自测" aria-label="Permalink to &quot;自测&quot;">​</a></h2><details><summary><b>1. tmagic-editor 为什么要拆成两个 HTML 文件（index.html + runtime.html）？三个核心工程诉求是什么？</b></summary><p>拆成双进程的三个理由：<strong>样式隔离、体积隔离、坐标隔离</strong>。</p><ul><li>样式隔离：编辑器引入的 Monaco / element-plus / moveable 等全局样式不能污染画布；iframe 天然自带 DOM 沙箱。</li><li>体积隔离：Monaco-editor 本身就有 ~2 MB（gzip），画布根本不需要；双入口 build 让 runtime 产物独立于编辑器，画布只装真正需要的运行时。</li><li>坐标隔离：画布需要 <code>position: absolute</code> 的自由布局；如果和编辑器混在同一 DOM 层级，<code>getBoundingClientRect()</code> 的 offset 会被外层容器稀释，选中框永远对不准。</li></ul><p>iframe 是工程权衡后的选择，不是功能限制。理论上用 Shadow DOM 也能实现样式隔离、用 Code Splitting 实现体积隔离、手动计算多层 offset 解决坐标——但复杂度远高于拆进程。</p></details><details><summary><b>2. MonacoEnvironment 为什么必须在 app.use(editorPlugin) 之前配？顺序颠倒会发生什么？</b></summary><p>Monaco-editor 在第一次调用 <code>create(...)</code> 时就会立即读取 <code>globalThis.MonacoEnvironment.getWorker</code> 来初始化 workers。如果此时 MonacoEnvironment 还没设置：</p><ul><li>Monaco 会 fallback 到默认的 worker URL（<code>./vs/base/worker/workerMain.js</code>），在 Vite dev 服务器上找不到这个路径；</li><li>报错不会直接抛出来——Monaco 的错误处理会吞掉它，返回一个&quot;不工作的 Monaco 实例&quot;；</li><li>表现就是：左侧 / 右侧面板里所有需要 code editor 的位置（code action 编辑、数据源 code block、schema 查看）都是空白输入框，没有任何提示。</li></ul><p>修复就是在 <code>src/main.ts</code> 最顶部、import editorPlugin 之后、<code>app.use(editorPlugin, adapter)</code> 之前配好 MonacoEnvironment。官方 playground 也是这么写的。</p></details><details><summary><b>3. 从 src/runtime/App.vue 的视角，描述 DSL 从编辑器推到画布渲染的完整链路。中间经过哪几层响应式包装？</b></summary><p>链路分 6 步，每一步都有响应式包装：</p><ol><li>编辑器 <code>TMagicEditor v-model</code> 的 dsl ref 变化 → 通过 stage 推给 iframe；</li><li><code>window.magic.updateRootConfig(dsl)</code> 被调用 → <code>@tmagic/vue-runtime-help</code> 的 <code>useEditorDsl()</code> 内部拿到 config 对象；</li><li><code>root.value = reactive(config)</code> → Vue 把完整 MApp 包成 reactive 对象；</li><li><code>pageConfig = computed(() =&gt; root.items[curPageId])</code> → 计算出当前页面；</li><li><code>&lt;component :is=&quot;pageComponent&quot; :config=&quot;pageConfig&quot;&gt;</code> → Vue 响应式渲染 Page 组件；</li><li>Page 组件内部递归渲染 items 数组里的每个子组件，直到真实 DOM 出现在 iframe 画布。</li></ol><p>每层之间用 Vue 的 reactive / ref / computed 连接，任何一层数据变化都会自动向上冒泡到真实 DOM。这也是为什么&quot;所见即所得&quot;能工作——编辑器侧拖组件、改属性，DSL 变化经 updateRootConfig 一路冒到 iframe，画布自动重渲染。</p></details>`,44)])])}const m=e(n,[["render",d]]);export{u as __pageData,m as default};
